# print covers with placements
from functools import lru_cache
G=['.##.# #'.replace(' ',''),'######',' .##.#..'.replace(' ',''),' ..###..'.replace(' ', '')]
# use explicit
G=['.##.##.','######.','.##.#..','..###..']
S={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x=='#'}
shapes=[]
for r in range(3):
 for c in range(6):
  q={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if q<=S: shapes.append((q,'1'))
  for missing in range(4):
   q={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}-{[(r,c),(r,c+1),(r+1,c),(r+1,c+1)][missing]}
   if q<=S: shapes.append((q,str(missing)))
by={p:[] for p in S}
for q,k in shapes:
 for p in q: by[p].append((q,k))
def rec(rem,ans):
 if not rem: return ans
 p=min(rem,key=lambda x:sum(q<=rem for q,k in by[x]))
 for q,k in by[p]:
  if q<=rem:
   z=rec(rem-q,ans+[(q,k)])
   if z:return z
print(len(S),rec(S,[]))
